10	export function AdminUserSearch() {
11	  const router = useRouter();
12	  const params = useSearchParams();
13	  const [value, setValue] = React.useState(params.get("q") ?? "");
14	
15	  function submit(e: React.FormEvent) {
16	    e.preventDefault();
17	    const next = new URLSearchParams();
18	    if (value.trim()) next.set("q", value.trim());
19	    router.push(`/admin/users${next.toString() ? `?${next}` : ""}`);
20	  }
21	
22	  return (
23	    <form onSubmit={submit} className="flex flex-wrap items-end gap-3">
24	      <Field label={t("admin.usersSearchLabel")}>
25	        {(p) => (
26	          <Input
27	            {...p}
28	            type="search"
29	            value={value}
30	            onChange={(e) => setValue(e.target.value)}
31	            placeholder={t("admin.usersSearchPlaceholder")}
32	          />
33	        )}
34	      </Field>
35	      <Button type="submit" icon={Search}>
36	        {t("admin.usersSearch")}
37	      </Button>
38	    </form>
39	  );
40	}
