29	  function Button(
30	    { variant = "primary", icon: Icon, full, className = "", children, type = "button", ...rest },
31	    ref,
32	  ) {
33	    const isQuiet = variant === "quiet";
34	    return (
35	      <button
36	        ref={ref}
37	        type={type}
38	        className={[
39	          "inline-flex items-center justify-center gap-2.5 whitespace-nowrap rounded-btn border font-body font-bold leading-tight",
40	          "text-base transition-colors duration-200 ease-[cubic-bezier(0.33,0.1,0.25,1)]",
41	          "disabled:cursor-not-allowed disabled:opacity-60",
42	          isQuiet ? "" : "min-h-12 px-[22px] py-2.5",
43	          full ? "w-full" : "",
44	          VARIANTS[variant],
45	          className,
46	        ]
47	          .filter(Boolean)
48	          .join(" ")}
49	        {...rest}
50	      >
51	        {Icon ? <Icon size={20} strokeWidth={2} aria-hidden="true" /> : null}
52	        {children}
53	      </button>
54	    );
55	  },
56	);
